  ('ar', 'site.meta.title', $json$"JayV — وكلاء ذكاء اصطناعي يبرمجون، مع دليل على أن الكود يعمل"$json$::jsonb),
  ('fr', 'site.meta.title', $json$"JayV — des agents d'IA qui codent, avec la preuve que ça marche"$json$::jsonb),
  ('ru', 'site.meta.title', $json$"JayV — ИИ-агенты, которые пишут код, с доказательством, что он работает"$json$::jsonb),
  ('ja', 'site.meta.title', $json$"JayV — コードを書く AI エージェント、動く証拠付きで"$json$::jsonb),
