  ('zh-CN', 'site.proof.ci.title', $json$"CI 中的同样证据"$json$::jsonb),
  ('hi', 'site.proof.ci.title', $json$"CI में वही सबूत"$json$::jsonb),
  ('ar', 'site.proof.ci.title', $json$"الدليل نفسه في CI"$json$::jsonb),
  ('fr', 'site.proof.ci.title', $json$"La même preuve en CI"$json$::jsonb),
