  ('de', 'site.proof.ci.title', $json$"Derselbe Beweis in der CI"$json$::jsonb),
  ('en', 'site.proof.ci.detail', $json$"jayv run --validate runs a request in a pipeline with the gate and the validator, exits with a code the pipeline understands and writes the summary for the pull request."$json$::jsonb),
  ('pt-BR', 'site.proof.ci.detail', $json$"O jayv run --validate roda um pedido num pipeline com a portaria e o validador, sai com um código que o pipeline entende e escreve o resumo para o pull request."$json$::jsonb),
  ('es', 'site.proof.ci.detail', $json$"jayv run --validate ejecuta una solicitud en un pipeline con la portería y el validador, termina con un código que el pipeline entiende y escribe el resumen para el pull request."$json$::jsonb),
  ('zh-CN', 'site.proof.ci.detail', $json$"jayv run --validate 在流水线中带着闸门和验证器运行请求，以流水线能识别的退出码结束，并为拉取请求写好摘要。"$json$::jsonb),
  ('hi', 'site.proof.ci.detail', $json$"jayv run --validate पाइपलाइन में गेट और वैलिडेटर के साथ अनुरोध चलाता है, पाइपलाइन समझ सके ऐसे कोड से बाहर निकलता है और पुल रिक्वेस्ट के लिए सारांश लिखता है।"$json$::jsonb),
  ('ar', 'site.proof.ci.detail', $json$"يشغّل jayv run --validate طلبًا في خط المعالجة مع البوابة والمدقق، وينتهي برمز يفهمه خط المعالجة، ويكتب الملخص لطلب الدمج."$json$::jsonb),
  ('fr', 'site.proof.ci.detail', $json$"jayv run --validate exécute une demande dans un pipeline avec le portail et le validateur, se termine avec un code que le pipeline comprend et écrit le résumé de la pull request."$json$::jsonb),
  ('ru', 'site.proof.ci.detail', $json$"jayv run --validate выполняет запрос в конвейере с проверкой на входе и валидатором, завершается кодом, понятным конвейеру, и пишет сводку для pull request."$json$::jsonb),
  ('ja', 'site.proof.ci.detail', $json$"jayv run --validate はゲートとバリデーター付きでパイプライン上のリクエストを実行し、パイプラインが理解できる終了コードで終わり、プルリクエスト用の要約を書きます。"$json$::jsonb),
  ('de', 'site.proof.ci.detail', $json$"jayv run --validate führt eine Anfrage in einer Pipeline mit Eingangsprüfung und Validator aus, endet mit einem Code, den die Pipeline versteht, und schreibt die Zusammenfassung für den Pull Request."$json$::jsonb),
