  ('hi', 'site.security.processorsHint', $json$"वे सेवाएँ जिन पर JayV निर्भर है और हर एक को क्या मिलता है।"$json$::jsonb),
  ('ar', 'site.security.processorsHint', $json$"الخدمات التي يعتمد عليها JayV وما يتلقاه كل منها."$json$::jsonb),
