  ('zh-CN', 'site.security.processor.jev.use', $json$"请求文本，用于在智能体运行前进行分析，仅限使用 Jev 的套餐和请求。"$json$::jsonb),
  ('hi', 'site.security.processor.jev.use', $json$"अनुरोध का पाठ, किसी एजेंट के चलने से पहले उसका विश्लेषण करने के लिए, उन प्लान और अनुरोधों में जो Jev का उपयोग करते हैं।"$json$::jsonb),
