  ('de', 'site.security.step.policies.title', $json$"Schriftliche Sicherheitsrichtlinien"$json$::jsonb),
  ('en', 'site.security.step.policies.detail', $json$"Access control, change management, incident response, vendor review and data retention, approved and reviewed once a year."$json$::jsonb),
  ('pt-BR', 'site.security.step.policies.detail', $json$"Controle de acesso, gestão de mudanças, resposta a incidentes, avaliação de fornecedores e retenção de dados, aprovadas e revistas uma vez por ano."$json$::jsonb),
  ('es', 'site.security.step.policies.detail', $json$"Control de acceso, gestión de cambios, respuesta a incidentes, revisión de proveedores y retención de datos, aprobadas y revisadas una vez al año."$json$::jsonb),
  ('zh-CN', 'site.security.step.policies.detail', $json$"访问控制、变更管理、事件响应、供应商审查和数据保留，经批准并每年复审一次。"$json$::jsonb),
  ('hi', 'site.security.step.policies.detail', $json$"एक्सेस नियंत्रण, बदलाव प्रबंधन, घटना प्रतिक्रिया, विक्रेता समीक्षा और डेटा प्रतिधारण, स्वीकृत और साल में एक बार समीक्षित।"$json$::jsonb),
  ('ar', 'site.security.step.policies.detail', $json$"التحكم في الوصول وإدارة التغيير والاستجابة للحوادث ومراجعة الموردين والاحتفاظ بالبيانات، معتمدة وتُراجع مرة في السنة."$json$::jsonb),
  ('fr', 'site.security.step.policies.detail', $json$"Contrôle d'accès, gestion des changements, réponse aux incidents, évaluation des fournisseurs et conservation des données, approuvées et revues une fois par an."$json$::jsonb),
  ('ru', 'site.security.step.policies.detail', $json$"Управление доступом, управление изменениями, реагирование на инциденты, проверка поставщиков и хранение данных — утверждены и пересматриваются раз в год."$json$::jsonb),
  ('ja', 'site.security.step.policies.detail', $json$"アクセス制御、変更管理、インシデント対応、ベンダー評価、データ保持を定め、承認し、年 1 回見直します。"$json$::jsonb),
  ('de', 'site.security.step.policies.detail', $json$"Zugriffskontrolle, Änderungsmanagement, Vorfallreaktion, Lieferantenprüfung und Datenaufbewahrung, genehmigt und einmal im Jahr überprüft."$json$::jsonb),
  ('en', 'site.security.step.evidence.title', $json$"Controls in operation, with evidence"$json$::jsonb),
