  ('de', 'site.security.step.evidence.title', $json$"Kontrollen im Betrieb, mit Nachweisen"$json$::jsonb),
  ('en', 'site.security.step.evidence.detail', $json$"Access reviews, backups, monitoring and change approvals running on a schedule, with records kept for the auditor."$json$::jsonb),
  ('pt-BR', 'site.security.step.evidence.detail', $json$"Revisões de acesso, backups, monitoramento e aprovação de mudanças rodando numa rotina, com registros guardados para o auditor."$json$::jsonb),
  ('es', 'site.security.step.evidence.detail', $json$"Revisiones de acceso, copias de seguridad, monitoreo y aprobación de cambios en una rutina, con registros guardados para el auditor."$json$::jsonb),
  ('zh-CN', 'site.security.step.evidence.detail', $json$"按计划执行访问审查、备份、监控和变更审批，并为审计师保留记录。"$json$::jsonb),
  ('hi', 'site.security.step.evidence.detail', $json$"एक्सेस समीक्षा, बैकअप, निगरानी और बदलाव स्वीकृति तय समय पर चलती हैं, ऑडिटर के लिए रिकॉर्ड रखे जाते हैं।"$json$::jsonb),
  ('ar', 'site.security.step.evidence.detail', $json$"مراجعات الوصول والنسخ الاحتياطي والمراقبة واعتماد التغييرات وفق جدول، مع حفظ السجلات للمدقق."$json$::jsonb),
  ('fr', 'site.security.step.evidence.detail', $json$"Revues d'accès, sauvegardes, supervision et approbation des changements selon un calendrier, avec des traces conservées pour l'auditeur."$json$::jsonb),
  ('ru', 'site.security.step.evidence.detail', $json$"Проверки доступа, резервные копии, мониторинг и согласование изменений по графику, с записями для аудитора."$json$::jsonb),
  ('ja', 'site.security.step.evidence.detail', $json$"アクセスレビュー、バックアップ、監視、変更承認を定期的に実施し、監査人向けに記録を残します。"$json$::jsonb),
  ('de', 'site.security.step.evidence.detail', $json$"Zugriffsprüfungen, Backups, Überwachung und Änderungsfreigaben nach Plan, mit Aufzeichnungen für den Prüfer."$json$::jsonb),
