  ('ja', 'site.security.step.type2.detail', $json$"監査人が、数か月にわたって管理策が機能していたかを確認します。"$json$::jsonb),
  ('de', 'site.security.step.type2.detail', $json$"Der Prüfer bestätigt, dass die Kontrollen über mehrere Monate funktioniert haben."$json$::jsonb),
  ('en', 'site.security.report', $json$"Found a security problem? Tell the JayV team privately before publishing it, and we will say when it is fixed."$json$::jsonb),
  ('pt-BR', 'site.security.report', $json$"Achou um problema de segurança? Avise a equipe do JayV em particular antes de publicar, e diremos quando estiver corrigido."$json$::jsonb),
  ('es', 'site.security.report', $json$"¿Encontraste un problema de seguridad? Avisa al equipo de JayV en privado antes de publicarlo y te diremos cuándo esté corregido."$json$::jsonb),
  ('zh-CN', 'site.security.report', $json$"发现了安全问题？请在公开前私下告知 JayV 团队，修复后我们会告诉你。"$json$::jsonb),
  ('hi', 'site.security.report', $json$"कोई सुरक्षा समस्या मिली? प्रकाशित करने से पहले JayV टीम को निजी तौर पर बताएँ, और ठीक होने पर हम बताएँगे।"$json$::jsonb),
  ('ar', 'site.security.report', $json$"وجدت مشكلة أمنية؟ أبلغ فريق JayV بشكل خاص قبل نشرها، وسنخبرك عند إصلاحها."$json$::jsonb),
  ('fr', 'site.security.report', $json$"Vous avez trouvé un problème de sécurité ? Prévenez l'équipe JayV en privé avant de le publier, et nous vous dirons quand il sera corrigé."$json$::jsonb),
  ('ru', 'site.security.report', $json$"Нашли проблему безопасности? Сообщите команде JayV лично до публикации, и мы скажем, когда она будет исправлена."$json$::jsonb),
