  ('zh-CN', 'site.audit.description', $json$"谁在哪个项目中请求了什么、用了哪个智能体和模型、验证了哪些命令以及结果。不包含请求和回答的文本。"$json$::jsonb),
  ('hi', 'site.audit.description', $json$"किसने क्या माँगा, किस प्रोजेक्ट में, किस एजेंट और मॉडल से, सत्यापित कमांड और परिणाम। अनुरोधों और जवाबों का पाठ शामिल नहीं होता।"$json$::jsonb),
