  ('en', 'site.audit.columns', $json$"Up to 5,000 requests per file, newest first. Columns: date, member, project, status, gate, agent, model, mode, commands, tools, validation, repairs, tokens and cost."$json$::jsonb),
  ('pt-BR', 'site.audit.columns', $json$"Até 5.000 pedidos por arquivo, os mais novos primeiro. Colunas: data, membro, projeto, status, portaria, agente, modelo, modo, comandos, ferramentas, validação, reparos, tokens e custo."$json$::jsonb),
  ('es', 'site.audit.columns', $json$"Hasta 5.000 solicitudes por archivo, las más nuevas primero. Columnas: fecha, miembro, proyecto, estado, portería, agente, modelo, modo, comandos, herramientas, validación, reparaciones, tokens y costo."$json$::jsonb),
  ('zh-CN', 'site.audit.columns', $json$"每个文件最多 5,000 个请求，最新的在前。列：日期、成员、项目、状态、闸门、智能体、模型、模式、命令、工具、验证、修复、token 和费用。"$json$::jsonb),
  ('hi', 'site.audit.columns', $json$"हर फ़ाइल में अधिकतम 5,000 अनुरोध, नए पहले। कॉलम: तारीख, सदस्य, प्रोजेक्ट, स्थिति, गेट, एजेंट, मॉडल, मोड, कमांड, टूल, सत्यापन, सुधार, टोकन और लागत।"$json$::jsonb),
  ('ar', 'site.audit.columns', $json$"حتى 5,000 طلب لكل ملف، الأحدث أولًا. الأعمدة: التاريخ، العضو، المشروع، الحالة، البوابة، الوكيل، النموذج، الوضع، الأوامر، الأدوات، التحقق، الإصلاحات، الرموز والتكلفة."$json$::jsonb),
  ('fr', 'site.audit.columns', $json$"Jusqu'à 5 000 demandes par fichier, les plus récentes d'abord. Colonnes : date, membre, projet, statut, portail, agent, modèle, mode, commandes, outils, validation, réparations, tokens et coût."$json$::jsonb),
  ('ru', 'site.audit.columns', $json$"До 5 000 запросов в файле, сначала новые. Столбцы: дата, участник, проект, статус, проверка на входе, агент, модель, режим, команды, инструменты, проверка, исправления, токены и стоимость."$json$::jsonb),
  ('ja', 'site.audit.columns', $json$"1 ファイルあたり最大 5,000 件、新しい順。列: 日付、メンバー、プロジェクト、状態、ゲート、エージェント、モデル、モード、コマンド、ツール、検証、修復、トークン、コスト。"$json$::jsonb),
  ('de', 'site.audit.columns', $json$"Bis zu 5.000 Anfragen pro Datei, neueste zuerst. Spalten: Datum, Mitglied, Projekt, Status, Eingangsprüfung, Agent, Modell, Modus, Befehle, Werkzeuge, Validierung, Reparaturen, Tokens und Kosten."$json$::jsonb),
